/** The API reference's data, generated by `scripts/render-api.ts`. */

export interface ApiTocEntry {
	id: string;
	text: string;
	depth: number;
}

/** One rendered page: the index (`""`), a namespace (`System/Text`) or a type
 *  (`System/Text/Json`). */
export interface ApiPage {
	path: string;
	title: string;
	description: string;
	html: string;
	/** The page's own sections, for the sidebar. */
	toc: ApiTocEntry[];
}

/** A namespace and its types, for the sidebar. */
export interface ApiNavNamespace {
	name: string;
	href: string;
	types: { name: string; href: string }[];
}

/** An API page's `<title>` (the view sets it in `@head`; see lib/titles.ts). */
export function api_title(page: ApiPage | undefined): string {
	return page?.title ?? "Not found — Nomen API";
}

/** The `<head>` elements for an API page (`page` is undefined for a 404). */
export function api_head(
	url: URL,
	page: ApiPage | undefined,
): (
	| { title: string }
	| { name: string; content: string }
	| { property: string; content: string }
)[] {
	const title = api_title(page);
	const description = page?.description ?? "";
	return [
		{ name: "description", content: description },
		{ property: "og:title", content: title },
		{ property: "og:description", content: description },
		{ property: "og:type", content: "website" },
		{ property: "og:url", content: url.href },
	];
}
